/* ddl_basic.sql -- synthetic fixture for the FR-SCHEMA DDL reader */
CREATE DOMAIN D_NAME AS VARCHAR(40) CHARACTER SET UTF8 DEFAULT 'X' NOT NULL;
CREATE DOMAIN D_QTY AS INTEGER DEFAULT 0 CHECK (VALUE >= 0);
CREATE GENERATOR GEN_CUSTOMER_ID;
CREATE SEQUENCE GEN_ORDERS_ID;

CREATE TABLE CUSTOMER (
  ID BIGINT NOT NULL,
  NAME D_NAME,
  CITY VARCHAR(30),
  CONSTRAINT PK_CUSTOMER PRIMARY KEY (ID),
  CONSTRAINT UQ_CUSTOMER_NAME UNIQUE (NAME)
);

CREATE TABLE ORDERS (
  ID BIGINT NOT NULL PRIMARY KEY,
  CUSTOMER_ID BIGINT NOT NULL,
  QTY D_QTY,
  TOTAL NUMERIC(12,2) DEFAULT 0,
  NOTE BLOB SUB_TYPE TEXT,
  CONSTRAINT FK_ORDERS_CUSTOMER FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMER (ID) ON DELETE CASCADE
);

ALTER TABLE ORDERS ADD STATUS SMALLINT DEFAULT 1;

CREATE INDEX IDX_ORDERS_QTY ON ORDERS (QTY);
